#!/usr/bin/env python3
"""标准库离线统计。保留坏轮次；不把回调节奏当成实际呈现 FPS。"""
import argparse
import json
import math
import statistics
from pathlib import Path


COMPARE_KEYS = ("scenarioId", "scenarioVersion", "seed", "deviceId", "engine", "backend",
                "quality", "workload", "targetFPS", "toleranceMs", "environment", "protocol")


def finite(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def percentile(values, fraction):
    """Nearest-rank: sorted[ceil(p*n)-1]，空样本不补零。"""
    return sorted(values)[max(0, math.ceil(fraction * len(values)) - 1)] if values else None


def intervals(values, budget, tolerance):
    if not values:
        return None
    longest = streak = 0
    for x in values:
        streak = streak + 1 if x > budget + tolerance else 0
        longest = max(longest, streak)
    span = sum(values)
    return {"samples": len(values), "intervalSpanMs": span,
            "callbackOrSubmissionFPS": len(values) * 1000 / span,
            "p50Ms": percentile(values, .5), "p95Ms": percentile(values, .95),
            "p99Ms": percentile(values, .99), "maxMs": max(values),
            "overBudgetPercent": 100 * sum(v > budget + tolerance for v in values) / len(values),
            "over2BCount": sum(v > 2 * budget for v in values),
            "longestOverBudgetStreak": longest}


def read_run(file):
    result = {"file": str(file.resolve()), "valid": False, "reasons": [], "notes": []}
    try:
        raw = json.loads(file.read_text(encoding="utf-8"))
        if not isinstance(raw, dict):
            raise ValueError("根节点必须是对象")
        meta = raw.get("metadata", {})
        result["metadata"] = meta
        reasons = result["reasons"]
        if raw.get("schemaVersion") != 1:
            reasons.append("不支持的 schemaVersion")
        if raw.get("status") != "ok":
            reasons.append("本轮执行失败或缺少 status:ok")
        if raw.get("failure"):
            reasons.append("存在 failure")
        validation = raw.get("validation") or {}
        if validation.get("passed") is not True or not str(validation.get("details", "")).strip():
            reasons.append("缺少实际工作负载/功能验证")
        if not isinstance(meta, dict):
            raise ValueError("metadata 必须是对象")
        for key in (*COMPARE_KEYS, "buildId"):
            if key not in meta:
                reasons.append(f"metadata 缺少 {key}")
        fps, tolerance = meta.get("targetFPS"), meta.get("toleranceMs")
        if not finite(fps) or fps <= 0 or not finite(tolerance) or tolerance < 0:
            raise ValueError("targetFPS/toleranceMs 无效")
        duration = raw.get("durationMs")
        if not finite(duration) or duration <= 0:
            raise ValueError("durationMs 无效")
        result["durationMs"] = duration
        if "started-hidden" in raw.get("warnings", []) or any(
            event.get("state") != "visible" for event in raw.get("visibilityChanges", [])
        ):
            reasons.append("采样窗口进入后台/不可见")
        if raw.get("resizeEvents", 0):
            reasons.append("稳态窗口发生 resize；如需测试 resize 请单列专项场景")
        if any(raw.get("dropped", {}).values()):
            reasons.append("采样缓冲溢出")
        if raw.get("pageErrors") or raw.get("droppedPageErrors", 0):
            reasons.append("存在页面未捕获异常")
        budget = 1000 / fps
        for field, label in (("rafIntervalsMs", "raf"), ("gameFrameIntervalsMs", "gameFrames")):
            values = raw.get(field, [])
            if not isinstance(values, list) or any(not finite(v) or v <= 0 for v in values):
                raise ValueError(f"{field} 必须是有限正数数组")
            if sum(values) > duration + 1:
                reasons.append(f"{field} 间隔总和超出窗口")
            result[label] = intervals(values, budget, tolerance)
            if not values:
                result["notes"].append(f"{label} 无样本，不能填零或推导实际呈现 FPS")
        if not result.get("raf") and not result.get("gameFrames"):
            reasons.append("没有可分析的帧节奏样本")
        expected = (meta.get("protocol") or {}).get("durationSeconds")
        if finite(expected) and abs(duration - expected * 1000) > max(250, expected * 50):
            # 不删除真实卡顿：保留本轮统计并要求复核窗口延长原因。
            result["notes"].append("实际窗口偏离计划超过 5% 或 250ms；检查驱动等待/主线程长停顿，不得裁掉卡顿")
            result["windowReviewRequired"] = True
        if raw.get("capabilities", {}).get("longTasks") is True:
            tasks = raw.get("longTasks", [])
            for t in tasks:
                if not finite(t.get("startMs")) or not finite(t.get("durationMs")) or t["startMs"] < 0 or t["durationMs"] <= 0:
                    raise ValueError("longTasks 数据无效")
            result["longTasks"] = {"count": len(tasks), "totalMs": sum(
                max(0, min(duration, t["startMs"] + t["durationMs"]) - t["startMs"]) for t in tasks)}
        else:
            result["longTasks"] = None
        result["metrics"] = {}
        for name, metric in raw.get("metrics", {}).items():
            if not metric.get("unit") or metric.get("kind") not in ("measured", "estimated"):
                raise ValueError(f"{name} 单位/口径缺失")
            samples = metric.get("samples", [])
            if any(not finite(s.get("value")) or not finite(s.get("tMs")) or not 0 <= s["tMs"] <= duration + 1 for s in samples):
                raise ValueError(f"{name} 样本值/时间无效")
            values = [s["value"] for s in samples]
            result["metrics"][name] = {"unit": metric["unit"], "kind": metric["kind"],
                "samples": len(values), "first": values[0] if values else None,
                "last": values[-1] if values else None, "min": min(values) if values else None,
                "max": max(values) if values else None, "mean": statistics.mean(values) if values else None}
        result["valid"] = not reasons
    except (ValueError, OSError, TypeError, KeyError, AttributeError) as error:
        result["reasons"].append(str(error))
    return result


def aggregate(runs):
    valid = [r for r in runs if r["valid"]]
    out = {"totalRuns": len(runs), "validRuns": len(valid), "exploratory": len(valid) < 3,
           "buildIds": sorted({str(r.get("metadata", {}).get("buildId")) for r in runs}), "series": {}}
    for group in ("raf", "gameFrames"):
        series = [r[group] for r in valid if r.get(group)]
        for key in ("callbackOrSubmissionFPS", "p50Ms", "p95Ms", "p99Ms", "maxMs", "overBudgetPercent", "over2BCount"):
            values = [s[key] for s in series]
            if values:
                out["series"][f"{group}.{key}"] = {"runs": len(values), "median": statistics.median(values),
                                                     "min": min(values), "max": max(values)}
    return out


def differences(runs):
    if not runs:
        return ["没有轮次文件"]
    differences = []
    # 无效轮次也参与环境核对，不能静默舍弃失败后选择有利样本。
    ref = runs[0].get("metadata", {})
    for run in runs[1:]:
        meta = run.get("metadata", {})
        for key in COMPARE_KEYS:
            if meta.get(key) != ref.get(key):
                differences.append(f"{Path(run['file']).name}: {key} 不同")
    return sorted(set(differences))


def load_runs(location):
    p = Path(location)
    files = sorted(p.glob("run-*.json")) if p.is_dir() else [p]
    if not files:
        raise ValueError(f"{p}: 没有 run-*.json")
    return [read_run(f) for f in files]


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--baseline", required=True)
    parser.add_argument("--candidate")
    parser.add_argument("--out", required=True)
    args = parser.parse_args()
    groups = {"baseline": load_runs(args.baseline)}
    if args.candidate:
        groups["candidate"] = load_runs(args.candidate)
    all_runs = [r for runs in groups.values() for r in runs]
    diffs = differences(all_runs)
    # 每组必须对应一个构建；前后构建不同是允许且预期的。
    for label, runs in groups.items():
        if len({str(r.get("metadata", {}).get("buildId")) for r in runs}) != 1:
            diffs.append(f"{label}: 同组混入多个 buildId")
    out = {"schemaVersion": 1, "comparable": not diffs, "differences": diffs,
           "groups": {k: {"aggregate": aggregate(v), "runs": v} for k, v in groups.items()},
           "deltas": {}, "automaticAcceptance": False}
    if not diffs and "candidate" in groups:
        base = out["groups"]["baseline"]["aggregate"]["series"]
        cand = out["groups"]["candidate"]["aggregate"]["series"]
        for key in base.keys() & cand.keys():
            before, after = base[key]["median"], cand[key]["median"]
            out["deltas"][key] = {"baseline": before, "candidate": after, "absolute": after - before,
                                   "percent": 100 * (after - before) / before if before else None}
    report = ["# 游戏性能采样报告", "", "rAF = 浏览器回调节奏；gameFrames = 显式游戏整帧提交节奏，均不保证实际屏幕呈现。",
              "百分位使用 nearest-rank；先逐轮统计，再汇总中位数及轮间范围。不剔除长帧。", "",
              f"配置可比：{'是' if not diffs else '否'}；本工具不自动判定优化验收通过。"]
    report.extend(f"- {d}" for d in diffs)
    for label, value in out["groups"].items():
        a = value["aggregate"]
        report.extend(["", f"## {label}", "", f"有效轮次 {a['validRuns']}/{a['totalRuns']}；构建 {', '.join(a['buildIds'])}。"])
        if a["exploratory"]:
            report.append("重复不足 3 轮：仅作探索性证据。")
        report.extend(["", "| 指标 | 轮中位数 | 轮间最小–最大 |", "|---|---|---|"])
        for key, stats in a["series"].items():
            report.append(f"| {key} | {stats['median']:.4g} | {stats['min']:.4g}–{stats['max']:.4g} |")
        report.append("")
        for run in value["runs"]:
            report.append(f"- 原始文件：`{run['file']}`；{'有效' if run['valid'] else '无效'}；" +
                          "；".join(run["reasons"] + run["notes"]))
    report.extend(["", "缺少 GPU/进程内存/实际呈现数据时为不可用，不能补零。页面异常数量不能直接当线上错误率。",
                   "检查 summary.json 中逐轮长任务、带单位的测量/估算、窗口复核项和差值；功能、输入、画质与波动仍需验收。"])
    target = Path(args.out)
    target.mkdir(parents=True, exist_ok=True)
    for name, data in (("summary.json", json.dumps(out, ensure_ascii=False, indent=2, allow_nan=False)),
                       ("report.md", "\n".join(report) + "\n")):
        with (target / name).open("x", encoding="utf-8") as stream:
            stream.write(data)
    print(f"报告已保存：{target.resolve()}")
    return 2 if diffs or any(not r["valid"] for r in all_runs) else 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (ValueError, OSError) as error:
        raise SystemExit(str(error))

/* 开发诊断采集器：不启动游戏循环，不改渲染器，不发送网络请求。 */
(() => {
  "use strict";
  if (Object.prototype.hasOwnProperty.call(globalThis, "__webGamePerf")) {
    if (globalThis.__webGamePerf?.probeVersion === 1) return;
    throw new Error("__webGamePerf 已被其他代码占用");
  }
  let active = null;
  const clock = () => performance.now();
  const append = (list, value, key) => {
    if (list.length < active.maxSamples) list.push(value);
    else active.result.dropped[key]++;
  };
  function collectLongTasks(entries) {
    if (!active) return;
    for (const entry of entries) {
      // 不把测量开始前的长任务整体计入当前窗口。
      const start = Math.max(entry.startTime, active.start);
      const end = Math.min(entry.startTime + entry.duration, clock());
      if (end > start) append(active.result.longTasks,
        { startMs: start - active.start, durationMs: end - start }, "longTasks");
    }
  }
  function record(name, value, unit, kind = "measured") {
    if (!active) return false;
    if (!/^[A-Za-z][\w.:-]{0,95}$/.test(name) || !Number.isFinite(value) ||
        typeof unit !== "string" || !unit || unit.length > 24 ||
        !["measured", "estimated"].includes(kind)) {
      throw new Error("record 需要合法名称、有限数值、单位和 measured/estimated 口径");
    }
    const metrics = active.result.metrics;
    if (metrics[name] && (metrics[name].unit !== unit || metrics[name].kind !== kind)) {
      throw new Error("同名指标不能更换单位或测量口径");
    }
    if (active.metricCount >= active.maxSamples) {
      active.result.dropped.metricSamples++;
      return false;
    }
    metrics[name] ??= { unit, kind, samples: [] };
    metrics[name].samples.push({ tMs: clock() - active.start, value });
    active.metricCount++;
    return true;
  }
  function start({ metadata = {}, maxSamples = 120000, sampleJsHeap = false } = {}) {
    if (active) throw new Error("采集已启动，请先 stop");
    if (!Number.isInteger(maxSamples) || maxSamples < 1 || maxSamples > 1000000) {
      throw new Error("maxSamples 须为 1–1000000 的整数");
    }
    const result = {
      schemaVersion: 1, metadata: JSON.parse(JSON.stringify(metadata)),
      startedAt: new Date().toISOString(), durationMs: null,
      rafIntervalsMs: [], gameFrameIntervalsMs: [], longTasks: [],
      metrics: Object.create(null), visibilityChanges: [], resizeEvents: 0,
      dropped: { raf: 0, gameFrames: 0, longTasks: 0, metricSamples: 0, events: 0 },
      capabilities: { longTasks: false, jsHeap: false }, warnings: [],
    };
    active = { start: clock(), result, maxSamples, metricCount: 0,
      lastRaf: null, lastGameFrame: null, observer: null, lastHeap: -Infinity };
    if (document.visibilityState !== "visible") result.warnings.push("started-hidden");
    active.visibility = () => append(result.visibilityChanges, {
      tMs: clock() - active.start, state: document.visibilityState,
    }, "events");
    active.resize = () => { result.resizeEvents++; };
    document.addEventListener("visibilitychange", active.visibility);
    globalThis.addEventListener("resize", active.resize);
    if (typeof PerformanceObserver !== "undefined" &&
        PerformanceObserver.supportedEntryTypes?.includes("longtask")) {
      try {
        active.observer = new PerformanceObserver(list => collectLongTasks(list.getEntries()));
        active.observer.observe({ type: "longtask", buffered: false });
        result.capabilities.longTasks = true;
      } catch { result.warnings.push("longtask-observer-unavailable"); }
    }
    function tick(t) {
      if (!active) return;
      if (active.lastRaf !== null && t > active.lastRaf) {
        append(result.rafIntervalsMs, t - active.lastRaf, "raf");
      }
      active.lastRaf = t;
      if (sampleJsHeap && t - active.lastHeap >= 1000) {
        active.lastHeap = t;
        const bytes = performance.memory?.usedJSHeapSize;
        if (Number.isFinite(bytes)) {
          result.capabilities.jsHeap = true;
          record("memory.jsHeap", bytes, "bytes");
        }
      }
      active.rafId = requestAnimationFrame(tick);
    }
    active.rafId = requestAnimationFrame(tick);
    return { startedAt: result.startedAt };
  }
  function gameFrame(t = clock()) {
    if (!active) return false;
    if (!Number.isFinite(t) || t < active.start ||
        (active.lastGameFrame !== null && t <= active.lastGameFrame)) {
      throw new Error("gameFrame 需要 performance 时间轴上递增的毫秒时间");
    }
    if (active.lastGameFrame !== null) {
      append(active.result.gameFrameIntervalsMs, t - active.lastGameFrame, "gameFrames");
    }
    active.lastGameFrame = t;
    return true;
  }
  function stop() {
    if (!active) throw new Error("没有运行中的采集");
    const session = active;
    cancelAnimationFrame(session.rafId);
    if (session.observer) {
      collectLongTasks(session.observer.takeRecords());
      session.observer.disconnect();
    }
    document.removeEventListener("visibilitychange", session.visibility);
    globalThis.removeEventListener("resize", session.resize);
    session.result.durationMs = clock() - session.start;
    active = null;
    return session.result;
  }
  Object.defineProperty(globalThis, "__webGamePerf", {
    configurable: true,
    value: Object.freeze({ probeVersion: 1, start, stop, record, gameFrame,
      isRunning: () => active !== null,
      isReady: () => active !== null && active.result.rafIntervalsMs.length > 0 }),
  });
})();

#!/usr/bin/env node
// 可选 Playwright 驱动；依赖从被测项目解析，不自动安装包或浏览器。
import fs from "node:fs/promises";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath, pathToFileURL } from "node:url";

function options(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i += 2) {
    if (!argv[i]?.startsWith("--") || !argv[i + 1] || argv[i + 1].startsWith("--")) {
      throw new Error("参数格式：--config 文件 --phase baseline|candidate --out 目录 [--playwright-module 模块路径]");
    }
    const key = argv[i].slice(2);
    if (!["config", "phase", "out", "playwright-module"].includes(key)) throw new Error(`未知参数 ${key}`);
    args[key] = argv[i + 1];
  }
  if (!args.config || !args.out || !["baseline", "candidate"].includes(args.phase)) {
    throw new Error("必须指定 --config、--phase baseline|candidate、--out");
  }
  return args;
}
async function timed(promise, ms, label) {
  let timer;
  try {
    return await Promise.race([promise, new Promise((_, reject) => {
      timer = setTimeout(() => reject(new Error(`${label} 超时 (${ms}ms)`)), ms);
    })]);
  } finally { clearTimeout(timer); }
}
async function save(file, value) {
  // 不覆盖已有轮次。对比数据必须可追溯。
  await fs.writeFile(file, JSON.stringify(value, null, 2), { flag: "wx" });
}
function validate(c) {
  for (const key of ["url", "scenarioModule", "scenarioId", "scenarioVersion", "buildId", "deviceId", "engine", "backend"]) {
    if (typeof c[key] !== "string" || !c[key].trim()) throw new Error(`配置缺少 ${key}`);
  }
  if (!["http:", "https:"].includes(new URL(c.url).protocol)) throw new Error("url 须为实际 HTTP(S) 地址");
  for (const key of ["seed", "quality", "workload"]) {
    if (c[key] === undefined) throw new Error(`配置缺少 ${key}`);
  }
  for (const [key, fallback, min, max] of [
    ["durationSeconds", 30, 0.1, 86400], ["warmupSeconds", 5, 0, 3600],
    ["repeats", 3, 1, 100], ["targetFPS", 60, 1, 1000],
    ["toleranceMs", 1, 0, 1000], ["stepTimeoutSeconds", 30, 1, 3600],
    ["deviceScaleFactor", 1, 0.1, 8],
  ]) {
    c[key] ??= fallback;
    if (!Number.isFinite(c[key]) || c[key] < min || c[key] > max) throw new Error(`${key} 不在允许范围内`);
  }
  if (!Number.isInteger(c.repeats)) throw new Error("repeats 须为整数");
  c.browserName ??= "chromium";
  if (!["chromium", "firefox", "webkit"].includes(c.browserName)) throw new Error("不支持的 browserName");
  c.headless ??= false;
  if (typeof c.headless !== "boolean") throw new Error("headless 须为布尔值");
  c.viewport ??= { width: 1280, height: 720 };
  if (![c.viewport.width, c.viewport.height].every(v => Number.isInteger(v) && v > 0)) throw new Error("viewport 无效");
  c.cacheProtocol ??= "fresh-context";
  if (c.cacheProtocol !== "fresh-context") throw new Error("本驱动只实现 fresh-context；热启动请编写专用驱动并记录策略");
  c.profile ??= "steady";
  if (!["steady", "first-use"].includes(c.profile)) throw new Error("profile 须为 steady 或 first-use");
  if (c.profile === "first-use" && c.warmupSeconds !== 0) throw new Error("first-use 必须显式设 warmupSeconds: 0");
  return c;
}
async function main() {
  const args = options(process.argv.slice(2));
  const configFile = path.resolve(args.config);
  const projectDir = path.dirname(configFile);
  const c = validate(JSON.parse(await fs.readFile(configFile, "utf8")));
  const scenario = await import(pathToFileURL(path.resolve(projectDir, c.scenarioModule)).href);
  for (const hook of ["setup", "exercise", "validate"]) {
    if (typeof scenario[hook] !== "function") throw new Error(`场景模块缺少 ${hook}(page, context)`);
  }
  const requireProject = createRequire(path.join(projectDir, "package.json"));
  let pw;
  try { pw = requireProject(args["playwright-module"] || "playwright"); }
  catch (error) { throw new Error(`无法加载 Playwright：${error}；请检查项目已安装包及其 Node 版本要求，或 --playwright-module 指定可用模块。未自动安装任何依赖。`); }
  const out = path.resolve(args.out);
  await fs.mkdir(out, { recursive: true });
  const probePath = path.join(path.dirname(fileURLToPath(import.meta.url)), "browser_probe.js");
  let browser;
  try { browser = await pw[c.browserName].launch({ headless: c.headless }); }
  catch (error) {
    await save(path.join(out, `session-failure-${Date.now()}.json`),
      { status: "failed", stage: "browser-launch", message: String(error), buildId: c.buildId });
    throw error;
  }
  let failures = 0;
  try {
    for (let index = 1; index <= c.repeats; index++) {
      const stem = `run-${args.phase}-${String(index).padStart(3, "0")}`;
      const file = path.join(out, `${stem}.json`);
      try { await fs.access(file); throw new Error(`拒绝覆盖 ${file}；请更换输出目录`); }
      catch (error) { if (error.code !== "ENOENT") throw error; }
      const context = await browser.newContext({ viewport: c.viewport, deviceScaleFactor: c.deviceScaleFactor });
      const page = await context.newPage();
      page.setDefaultTimeout(c.stepTimeoutSeconds * 1000);
      page.setDefaultNavigationTimeout(c.stepTimeoutSeconds * 1000);
      const errors = [];
      let droppedErrors = 0;
      page.on("pageerror", error => {
        if (errors.length < 100) errors.push(String(error)); else droppedErrors++;
      });
      const ctx = { config: c, phase: args.phase, index, seed: c.seed, mode: "setup", durationMs: 0 };
      let raw, stage = "navigation", failure = null, validation = null, metadata;
      try {
        await page.addInitScript({ path: probePath });
        const response = await page.goto(c.url, { waitUntil: "domcontentloaded" });
        if (response && !response.ok()) throw new Error(`入口 HTTP ${response.status()}`);
        stage = "setup";
        await timed(scenario.setup(page, ctx), c.stepTimeoutSeconds * 1000, stage);
        // setup 必须等待真实可玩条件；此值包含导航和 setup 操作，不自动等同 LCP。
        const readyFromNavigationMs = await page.evaluate(() => performance.now());
        if (c.warmupSeconds > 0) {
          stage = "warmup";
          await timed(scenario.exercise(page, { ...ctx, mode: "warmup", durationMs: c.warmupSeconds * 1000 }),
            (c.warmupSeconds + c.stepTimeoutSeconds) * 1000, stage);
          // 重新进入相同状态，但保留本页已预热资源；不得重新创建浏览器上下文。
          await timed(scenario.setup(page, { ...ctx, mode: "reset-after-warmup" }), c.stepTimeoutSeconds * 1000, "reset");
        }
        const environment = await page.evaluate(() => ({
          userAgent: navigator.userAgent, viewport: { width: innerWidth, height: innerHeight },
          dpr: devicePixelRatio,
          canvases: [...document.querySelectorAll("canvas")].map(x => ({ width: x.width, height: x.height })),
        }));
        metadata = {
          scenarioId: c.scenarioId, scenarioVersion: c.scenarioVersion, seed: c.seed,
          buildId: c.buildId, deviceId: c.deviceId, engine: c.engine, backend: c.backend,
          quality: c.quality, workload: c.workload, targetFPS: c.targetFPS, toleranceMs: c.toleranceMs,
          environment: { ...environment, browserName: c.browserName, browserVersion: browser.version(), headless: c.headless },
          protocol: { profile: c.profile, cacheProtocol: c.cacheProtocol, warmupSeconds: c.warmupSeconds,
            durationSeconds: c.durationSeconds, sampleJsHeap: c.sampleJsHeap === true },
          run: { phase: args.phase, index },
        };
        stage = "sampling";
        await page.evaluate(({ metadata, maxSamples, sampleJsHeap, ready }) => {
          globalThis.__webGamePerf.start({ metadata, maxSamples, sampleJsHeap });
          globalThis.__webGamePerf.record("startup.readyFromNavigationMs", ready, "ms");
        }, { metadata, maxSamples: c.maxSamples ?? 120000, sampleJsHeap: c.sampleJsHeap === true,
          ready: readyFromNavigationMs });
        // 先获得完整间隔，再触发首次动作，避免卡顿落入 start→首回调的未知区间。
        stage = "probe-ready";
        await page.waitForFunction(() => globalThis.__webGamePerf.isReady());
        stage = "sampling";
        // exercise 必须实际驱动场景并在 durationMs 附近返回；过短返回也保留固定观察窗口。
        await timed(Promise.all([
          scenario.exercise(page, { ...ctx, mode: "measure", durationMs: c.durationSeconds * 1000 }),
          new Promise(resolve => setTimeout(resolve, c.durationSeconds * 1000)),
        ]), (c.durationSeconds + c.stepTimeoutSeconds) * 1000, stage);
        raw = await page.evaluate(() => globalThis.__webGamePerf.stop());
        stage = "validation";
        validation = await timed(scenario.validate(page, { ...ctx, mode: "validate" }), c.stepTimeoutSeconds * 1000, stage);
        if (!validation || validation.passed !== true || typeof validation.details !== "string" || !validation.details.trim()) {
          throw new Error("validate 必须返回 {passed: true, details: 实际工作负载/功能断言证据}；截图本身不是断言");
        }
        stage = "screenshot";
        await page.screenshot({ path: path.join(out, `${stem}.png`) });
      } catch (error) {
        failure = { stage, message: String(error) };
        if (!raw) {
          try { raw = await page.evaluate(() => globalThis.__webGamePerf?.isRunning() ? globalThis.__webGamePerf.stop() : null); }
          catch { /* 导航/崩溃导致采集器消失时仍保存失败文件。 */ }
        }
      } finally {
        if (typeof scenario.teardown === "function") {
          try { await timed(scenario.teardown(page, ctx), c.stepTimeoutSeconds * 1000, "teardown"); }
          catch (error) { failure ??= { stage: "teardown", message: String(error) }; }
        }
        try { await context.close(); }
        catch (error) { failure ??= { stage: "context-close", message: String(error) }; }
      }
      const result = { ...(raw || { schemaVersion: 1, metadata: metadata || { ...c, run: { phase: args.phase, index } } }),
        status: failure || errors.length || droppedErrors ? "failed" : "ok", validation,
        failure, pageErrors: errors, droppedPageErrors: droppedErrors };
      await save(file, result);
      if (result.status !== "ok") failures++;
      console.log(`${stem}: ${result.status} -> ${file}`);
    }
  } finally { await browser.close(); }
  if (failures) process.exitCode = 2;
}
main().catch(error => { console.error(String(error)); process.exitCode = 2; });
